-- Composed kernel-interpreted invocation, pure data: read the assembled authority
-- from rows, compile it, then execute the compiled graph with a declared
-- overlay-binding rule. No materialization, no child process, no harness.
SET NOCOUNT ON;
SET XACT_ABORT ON;
BEGIN TRANSACTION;
DECLARE @trigger_name nvarchar(517), @triggers CURSOR;
SET @triggers=CURSOR LOCAL FAST_FORWARD FOR
 SELECT QUOTENAME(s.name)+N'.'+QUOTENAME(t.name)
 FROM sys.triggers t JOIN sys.objects o ON o.object_id=t.parent_id
 JOIN sys.schemas s ON s.schema_id=o.schema_id
 WHERE o.type='U' AND s.name IN ('model','source')
 AND (t.name LIKE 'guard%' OR t.name LIKE '%immutable%');
OPEN @triggers;
FETCH NEXT FROM @triggers INTO @trigger_name;
WHILE @@FETCH_STATUS=0 BEGIN EXEC(N'DROP TRIGGER '+@trigger_name); FETCH NEXT FROM @triggers INTO @trigger_name; END;
CLOSE @triggers; DEALLOCATE @triggers;
GO
EXEC model.scaffold_capability @capability_id=N'run-declared-graph', @on_exists=N'REPLACE';
EXEC model.declare_contract @id=N'run-declared-graph-request.v1', @schema=N'{"type":"object","additionalProperties":true}';
EXEC model.declare_contract @id=N'run-declared-graph-result.v1', @schema=N'{"type":"object","additionalProperties":true}';
GO
EXEC model.declare_scenario
 @capability_id=N'run-declared-graph',
 @scenario=N'{"scenarioId":"run-declared-graph","name":"Run a capability by reading, compiling and executing its declared graph","inputId":"run-declared-graph-request","inputContract":"run-declared-graph-request.v1","eventId":"run-declared-graph-requested","eventAuthority":"run-declared-graph.v1","outcomeId":"run-declared-graph-result","outcomeContract":"run-declared-graph-result.v1","terminal":true,"root":true,"given":"one capability whose authority is assembled from declared rows","when":"the authority is compiled and the kernel scheduler interprets the graph","then":"the graph outcome and observed topology are returned"}',
 @operations=N'[{"operationId":"run-declared-graph.1","kind":"invoke-port","portId":"run-declared-graph-compile"},{"operationId":"run-declared-graph.2","kind":"invoke-port","portId":"run-declared-graph-execute"}]',
 @port_bindings=N'[{"portId":"run-declared-graph-compile","platformCapabilityId":"sda-semantic-execution-graph-compilation-port.v1","configuration":{"providerId":"sda-semantic-execution-graph-compilation.compileSemanticExecutionGraph"}},{"portId":"run-declared-graph-execute","platformCapabilityId":"sda-semantic-execution-graph-execution-port.v1","configuration":{"providerId":"sda-semantic-execution-graph-execution.executeSemanticExecutionGraph","providers":[{"providerProfileId":"sda-semantic-value-graph-provider.v1","module":"languages/typescript/runtimes/node/semantic-execution-graph-mechanic-provider.mjs","export":"createMechanicProvider","factory":true},{"providerProfileId":"sda-declared-read-graph-provider.v1","module":"languages/typescript/runtimes/node/semantic-execution-graph-declared-read-provider.mjs","export":"createDeclaredReadProvider","factory":true},{"providerProfileId":"sda-platform-effect-graph-provider.v1","module":"languages/typescript/runtimes/node/semantic-execution-graph-effect-provider.mjs","export":"createPlatformEffectProvider","factory":true}],"overlayBindings":[{"mechanicId":"sda-authority-transformation-port.v1","providerProfileId":"sda-semantic-value-graph-provider.v1","providerProfileDigest":"sha256:aca6d8863f8ab4557ab31692c6d67cb42a15a98ca2a38fab863db6c14f00d9fd","implementationRef":"sda-semantic-value-graph-provider.v1"},{"mechanicId":"object","providerProfileId":"sda-semantic-value-graph-provider.v1","providerProfileDigest":"sha256:aca6d8863f8ab4557ab31692c6d67cb42a15a98ca2a38fab863db6c14f00d9fd","implementationRef":"sda-semantic-value-graph-provider.v1"},{"mechanicId":"literal","providerProfileId":"sda-semantic-value-graph-provider.v1","providerProfileDigest":"sha256:aca6d8863f8ab4557ab31692c6d67cb42a15a98ca2a38fab863db6c14f00d9fd","implementationRef":"sda-semantic-value-graph-provider.v1"},{"mechanicId":"format","providerProfileId":"sda-semantic-value-graph-provider.v1","providerProfileDigest":"sha256:aca6d8863f8ab4557ab31692c6d67cb42a15a98ca2a38fab863db6c14f00d9fd","implementationRef":"sda-semantic-value-graph-provider.v1"},{"mechanicId":"path","providerProfileId":"sda-semantic-value-graph-provider.v1","providerProfileDigest":"sha256:aca6d8863f8ab4557ab31692c6d67cb42a15a98ca2a38fab863db6c14f00d9fd","implementationRef":"sda-semantic-value-graph-provider.v1"},{"mechanicId":"sda-embodiment-plan-port.v1","providerProfileId":"sda-declared-read-graph-provider.v1","providerProfileDigest":"sha256:c9f489958d52188c748ccc8ee45cc13393182369ec53c8ad52e8c4eaba8ba595","implementationRef":"sda-declared-read-graph-provider.v1"},{"mechanicId":"sda-governed-http-exchange-port.v1","providerProfileId":"sda-platform-effect-graph-provider.v1","providerProfileDigest":"sha256:945a4ff5c2a0c550f35a18296888f6941a303f02c17de3c942cacace2f7e1358","implementationRef":"sda-platform-effect-graph-provider.v1"},{"mechanicId":"sda-external-credential-reference-binding-port.v1","providerProfileId":"sda-platform-effect-graph-provider.v1","providerProfileDigest":"sha256:945a4ff5c2a0c550f35a18296888f6941a303f02c17de3c942cacace2f7e1358","implementationRef":"sda-platform-effect-graph-provider.v1"},{"mechanicId":"array","providerProfileId":"sda-semantic-value-graph-provider.v1","providerProfileDigest":"sha256:aca6d8863f8ab4557ab31692c6d67cb42a15a98ca2a38fab863db6c14f00d9fd","implementationRef":"sda-semantic-value-graph-provider.v1"},{"mechanicId":"let","providerProfileId":"sda-semantic-value-graph-provider.v1","providerProfileDigest":"sha256:aca6d8863f8ab4557ab31692c6d67cb42a15a98ca2a38fab863db6c14f00d9fd","implementationRef":"sda-semantic-value-graph-provider.v1"},{"mechanicId":"identity","providerProfileId":"sda-semantic-value-graph-provider.v1","providerProfileDigest":"sha256:aca6d8863f8ab4557ab31692c6d67cb42a15a98ca2a38fab863db6c14f00d9fd","implementationRef":"sda-semantic-value-graph-provider.v1"},{"mechanicId":"base64-decode-utf8","providerProfileId":"sda-semantic-value-graph-provider.v1","providerProfileDigest":"sha256:aca6d8863f8ab4557ab31692c6d67cb42a15a98ca2a38fab863db6c14f00d9fd","implementationRef":"sda-semantic-value-graph-provider.v1"},{"mechanicId":"equals","providerProfileId":"sda-semantic-value-graph-provider.v1","providerProfileDigest":"sha256:aca6d8863f8ab4557ab31692c6d67cb42a15a98ca2a38fab863db6c14f00d9fd","implementationRef":"sda-semantic-value-graph-provider.v1"},{"mechanicId":"filter","providerProfileId":"sda-semantic-value-graph-provider.v1","providerProfileDigest":"sha256:aca6d8863f8ab4557ab31692c6d67cb42a15a98ca2a38fab863db6c14f00d9fd","implementationRef":"sda-semantic-value-graph-provider.v1"},{"mechanicId":"length","providerProfileId":"sda-semantic-value-graph-provider.v1","providerProfileDigest":"sha256:aca6d8863f8ab4557ab31692c6d67cb42a15a98ca2a38fab863db6c14f00d9fd","implementationRef":"sda-semantic-value-graph-provider.v1"},{"mechanicId":"try-parse-json","providerProfileId":"sda-semantic-value-graph-provider.v1","providerProfileDigest":"sha256:aca6d8863f8ab4557ab31692c6d67cb42a15a98ca2a38fab863db6c14f00d9fd","implementationRef":"sda-semantic-value-graph-provider.v1"}]}}]';
GO
SELECT 'run_declared_graph' AS result_set, c.capability_id FROM model.capability c WHERE c.capability_id=N'run-declared-graph';
COMMIT TRANSACTION;
